// r148: RLS speed-up (0343) - static checks. Behaviour (same rows / same writes / same per-row answer, InitPlan, speed,
// re-run, drift): tests/db/r148-rls-initplan-0343.sql. The files are generated by scripts/gen-0343-rls-initplan.mjs.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
const r = (p) => readFileSync(new URL('../' + p, import.meta.url), 'utf8');
let n = 0;
const t = (name, fn) => { try { fn(); n++; console.log('  ok ' + name); } catch (e) { console.error('  FAIL ' + name + '\n' + (e && e.stack || e)); process.exitCode = 1; } };
const SQL = r('supabase/migrations/0343_r148_rls_initplan.sql'), APPLY = r('supabase/APPLY-0343.sql'), CASES = r('tests/db/r148-rls-initplan-0343-cases.sql');
const code = SQL.split('\n').filter((l) => !l.trim().startsWith('--')).join('\n');
const bare = code.replace(/'(?:[^']|'')*'/g, "''");   // policy names such as 'a42 quotes delete from shelf' are not statements

// the cases file: (tbl, rel, pol, cmd, pre_q, pre_c, new_q, new_c)
const V = String.raw`(null|\$x(\d+)\$[\s\S]*?\$x\d+\$)`;
const rowRe = new RegExp(String.raw`^\('([^']*)', '([^']*)', '((?:[^']|'')*)', '(.)', ` + [V, V, V, V].join(', ') + String.raw`\)[,;]$`, 'gm');
const val = (s) => (s === 'null' ? null : s.replace(/^\$x\d+\$/, '').replace(/\$x\d+\$$/, ''));
const cases = [...CASES.matchAll(rowRe)].map((m) => ({ tbl: m[1], pol: m[3].replace(/''/g, "'"), cmd: m[4], pq: val(m[5]), pc: val(m[7]), nq: val(m[9]), nc: val(m[11]) }));
// remove every "( SELECT schema.fn(...) AS alias)" wrapper and normalise blanks
const unwrap = (s) => {
  if (s == null) return null;
  let v = s.replace(/\s+/g, ' ').trim(), w;
  while ((w = v.replace(/\( SELECT ((?:public|auth)\.[a-z0-9_]+\((?:[^()]|\([^()]*\))*\)) AS [a-z0-9_]+\)/g, '$1')) !== v) v = w;
  return v;
};
const count = (s, re) => ((s || '').match(re) || []).length;

t('0343: in the manifest once, after 0340, plain words; APPLY carries it verbatim in one transaction; ASCII only', () => {
  const mf = r('supabase/migrations/MANIFEST');
  assert.equal(count(mf, /^forward  supabase\/migrations\/0343_r148_rls_initplan\.sql$/gm), 1);
  assert.ok(mf.indexOf('forward  supabase/migrations/0340_r136_audit_via.sql') < mf.indexOf('forward  supabase/migrations/0343_r148_rls_initplan.sql'));
  assert.match(mf, /# 0343 \(R148[^\n]*Nothing dropped or deleted\. Same rules, faster\. Safe to run twice\./);
  assert.ok(APPLY.includes(SQL.trim()), 'APPLY = the migration verbatim');
  assert.match(APPLY, /^begin;$/m); assert.equal(count(APPLY, /^begin;$/gm), 1); assert.equal(count(APPLY, /^commit;$/gm), 1);
  assert.ok(APPLY.indexOf('begin;') < APPLY.indexOf(SQL.trim()) && APPLY.indexOf('commit;') < APPLY.indexOf('-- VERIFY'));
  for (const s of [SQL, APPLY, CASES]) assert.ok(/^[\x09\x0a\x0d\x20-\x7e]*$/.test(s), 'ASCII');
  assert.ok(!/^\s*\\/m.test(APPLY), 'no psql meta-command'); assert.ok(!/\bcreate\s+(temp|temporary)\s+table\b/i.test(APPLY), 'no temp table');
  assert.match(r('scripts/db-test/run-all.sh'), /run "r148-rls-initplan-0343" "R148-RLS-INITPLAN-0343: ALL PASS \\\(21\/21\\\)" psql -q -f tests\/db\/r148-rls-initplan-0343\.sql/);
});
t('0343: additive - nothing dropped / deleted / re-created, no grant widened, only ALTER POLICY through the guard', () => {
  assert.doesNotMatch(bare, /\bdrop\s+(table|column|policy|schema|view|function|trigger|index)\b/i);
  assert.doesNotMatch(bare, /\bcreate\s+policy\b/i);
  assert.doesNotMatch(bare, /\bdelete\s+from\b/i); assert.doesNotMatch(bare, /\btruncate\b/i); assert.doesNotMatch(bare, /\bupdate\s+public\./i);
  assert.doesNotMatch(bare, /\bgrant\b/i);
  assert.equal(count(bare, /alter policy/gi), 0, 'no ALTER POLICY statement outside the guard');
  assert.equal(count(code, /alter policy/gi), 1, 'the only ALTER POLICY is the guarded format() inside _r343_wrap');
  assert.ok(code.includes("v_sql := pg_catalog.format('alter policy %I on %s', p_pol, v_rel::regclass);"), 'guarded ALTER');
  assert.match(code, /if v_q is distinct from p_pre_q or v_c is distinct from p_pre_c then\s+raise notice 'r148-0343: skip "%" on % \(differs/);
  assert.match(code, /exception when others then\s+raise notice 'r148-0343: skip/);
  assert.match(code, /if v_q is not distinct from p_post_q and v_c is not distinct from p_post_c then return 'done'; end if;/);
  for (const f of ['_r343_md5(text)', '_r343_wrap(text, text, text, text, text, text, text, text)', '_r343_unwrapped()'])
    for (const who of ['public', 'anon', 'authenticated']) assert.ok(code.includes(`revoke all on function public.${f} from ${who};`), f + ' ' + who);
});
t('0343: one guarded block per changed policy; the expressions it sets are the ones in the test data', () => {
  assert.ok(cases.length > 250, 'cases parsed: ' + cases.length);
  assert.equal(CASES.split('\n').filter((l) => /^\('/.test(l)).length, cases.length, 'every case row parsed');
  const blocks = [...SQL.matchAll(/^do \$r343\$ begin perform public\._r343_wrap\('([^']*)', '((?:[^']|'')*)', [^\n]*\n  (null|\$x\d+\$[\s\S]*?\$x\d+\$),\n  (null|\$x\d+\$[\s\S]*?\$x\d+\$)\); end \$r343\$;$/gm)];
  assert.equal(blocks.length, cases.length);
  assert.equal(new Set(blocks.map((b) => b[1] + '/' + b[2])).size, blocks.length, 'each policy once');
  for (const [i, b] of blocks.entries()) {
    const c = cases[i];
    assert.equal(b[1] + '/' + b[2].replace(/''/g, "'"), c.tbl + '/' + c.pol);
    assert.equal(val(b[3]), c.nq !== c.pq ? c.nq : null, c.pol + ' on ' + c.tbl + ' USING');
    assert.equal(val(b[4]), c.nc !== c.pc ? c.nc : null, c.pol + ' on ' + c.tbl + ' WITH CHECK');
  }
});
t('0343: same logic - unwrapping every (SELECT ...) gives exactly the pre-0343 expression; only wrappers are added', () => {
  for (const c of cases) {
    assert.equal(unwrap(c.nq), unwrap(c.pq), c.pol + ' on ' + c.tbl + ' USING');
    assert.equal(unwrap(c.nc), unwrap(c.pc), c.pol + ' on ' + c.tbl + ' WITH CHECK');
    const added = count(c.nq, /\( SELECT /g) + count(c.nc, /\( SELECT /g) - count(c.pq, /\( SELECT /g) - count(c.pc, /\( SELECT /g);
    assert.ok(added >= 1, c.pol + ' on ' + c.tbl + ': at least one call wrapped');
    assert.equal((c.nq == null) + ':' + (c.nc == null), (c.pq == null) + ':' + (c.pc == null), 'clauses kept');
  }
});
t('0343: what is wrapped - has_area / current_org_id / auth.uid / is_admin / user_role / can_create / can_delete with constant arguments; nothing bare left', () => {
  const unw = /(?<!SELECT )(?<![A-Za-z0-9_."])(public\.(has_area|current_org_id|is_admin|user_role|can_create|can_delete|can_edit|helm_pw_change_pending)|auth\.uid)\((('([^']|'')*'::[a-z ]+)(, '([^']|'')*'::[a-z ]+)*)?\)/;
  for (const c of cases) { assert.ok(!unw.test(c.nq || ''), c.pol + ' on ' + c.tbl + ': ' + c.nq); assert.ok(!unw.test(c.nc || ''), c.pol + ' on ' + c.tbl + ': ' + c.nc); }
  const all = cases.map((c) => (c.nq || '') + ' ' + (c.nc || '')).join(' ');
  assert.ok(count(all, /\( SELECT public\.has_area\(/g) >= 300, 'has_area wrapped');
  assert.ok(count(all, /\( SELECT auth\.uid\(\) AS uid\)/g) >= 10, 'auth.uid wrapped');
  assert.ok(/public\.chat_can_see\(conversation_id\)/.test(all) && !/SELECT public\.chat_can_see\(/.test(all), 'a call that reads a column stays per row');
  const cmds = new Set(cases.map((c) => c.cmd));
  for (const k of ['r', 'a', 'w', 'd', '*']) assert.ok(cmds.has(k), 'command ' + k);
  for (const tb of ['public.quotes', 'public.leads', 'public.event_tasks', 'public.inventory_items'])
    assert.ok(cases.some((c) => c.tbl === tb && (c.cmd === 'r' || c.cmd === '*')), tb + ' read rule changed');
});
t('0343: generator + VERIFY - reproducible from the canonical catalog; VERIFY counts what is still bare', () => {
  const g = r('scripts/gen-0343-rls-initplan.mjs');
  assert.match(g, /--build/); assert.match(g, /--check/); assert.match(g, /fixpoint/); assert.match(g, /unwrapAll\(a\.q\) !== unwrapAll\(b\.q\)/);
  assert.match(SQL, /^-- GENERATED by scripts\/gen-0343-rls-initplan\.mjs/m);
  assert.match(APPLY, /\('01 no policy calls a per-query helper [^']*', \(select count\(\*\) from public\._r343_unwrapped\(\)\) = 0\)/);
});
console.log(`r148-rls-initplan: ${n} passed`);
